/**
 * Unit tests for FitnessFunction.decode
 */
public class FitnessFunction_decode_TriageGen2Test {

    /**
     * Helper method to set the private field 'boundaries' via reflection 
     * because it is not exposed via public setters in the provided snippet.
     */
    private void setBoundaries(CMAESOptimizer.FitnessFunction fitnessFunction, double[][] boundaries) throws Exception {
        Field field = CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
        field.setAccessible(true);
        field.set(fitnessFunction, boundaries);
    }

    @Test
    public void testDecode_BoundariesIsNull() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        // boundaries is null by default via constructor

        double[] x = {1.0, 2.0, 3.0};
        double[] expected = {1.0, 2.0, 3.0};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-15);
        // Ensure it returns the same reference or identical content as per logic
        Assert.assertSame(x, result);
    }

    @Test
    public void testDecode_NormalOperation() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        // boundaries[0] is lower bound, boundaries[1] is upper bound
        double[][] boundaries = {
            {0.0, 10.0, -5.0}, // min
            {1.0, 20.0, 5.0}   // max
        };
        setBoundaries(fitnessFunction, boundaries);

        // x values in [0, 1] range for the transformation logic
        double[] x = {0.5, 0.5, 0.5};

        // Calculation:
        // i=0: (1.0 - 0.0) * 0.5 + 0.0 = 0.5
        // i=1: (20.0 - 10.0) * 0.5 + 10.0 = 15.0
        // i=2: (5.0 - (-5.0)) * 0.5 + (-5.0) = 10.0 * 0.5 - 5.0 = 0.0
        double[] expected = {0.5, 15.0, 0.0};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-15);
        Assert.assertNotSame(x, result); // Should be a new array
    }

    @Test
    public void testDecode_BoundariesZeroRange() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {5.0, 5.0},
            {5.0, 5.0}
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {0.0, 1.0};
        double[] expected = {5.0, 5.0};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-15);
    }

    @Test
    public void testDecode_EmptyArray() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {},
            {}
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {};
        double[] expected = {};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-15);
        Assert.assertEquals(0, result.length);
    }

    @Test
    public void testDecode_NegativeValues() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {-10.0, -20.0},
            {-5.0, -10.0}
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {0.0, 1.0};

        // i=0: (-5.0 - (-10.0)) * 0.0 + (-10.0) = 5.0 * 0.0 - 10.0 = -10.0
        // i=1: (-10.0 - (-20.0)) * 1.0 + (-20.0) = 10.0 * 1.0 - 20.0 = -10.0
        double[] expected = {-10.0, -10.0};

        double[] result = fitnessFunction.decode(x);

        Assert.assertArrayEquals(expected, result, 1e-15);
    }
}
